package greeter

import "testing"

func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"case folded and space to hyphen", "Ada Lovelace", "ada-lovelace"},
		{"runs of whitespace fold to a single hyphen", "A \t B\nC", "a-b-c"},
		{"leading and trailing whitespace trimmed", "  Ada  ", "ada"},
		{"empty input", "", ""},
		{"blank input", " \t\n ", ""},
		{"existing hyphens preserved", "well-known", "well-known"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Slug(tt.in); got != tt.want {
				t.Errorf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

package greeter

import "strings"

// Slug 把 name 转成 URL 友好的页面锚点 slug：小写化，把连续空白折成单个连字符，去掉首尾空白。
func Slug(name string) string {
	return strings.Join(strings.Fields(strings.ToLower(name)), "-")
}
